function isAccountBlockErr(e){if(!e)return false;const code=e.code;const msg=clErr(e).toLowerCase();if(code===190)return true;if(code===31&&/verify.{0,40}phone|phone number|payment method|add a payment|set up payment|verify your account|business verification|verify your identity|agree to the|accept the terms|terms and conditions|pending action/.test(msg))return true;if(/cannot access the app|log in to www.facebook|log into www.facebook/.test(msg))return true;if(/error validating access token|session has expired|invalid oauth|user has not authorized/.test(msg))return true;return false;}
function clLog(m,kind){const el=document.getElementById('cl-log');if(!el)return;const empty=document.getElementById('cl-log-empty');if(empty)empty.style.display='none';const gen=(typeof m==='function')?m:(()=>m);const html=gen();let k=kind;if(!k){if(/━/.test(html))k='sep';else if(/⛔/.test(html))k='err';else if(/✗/.test(html))k='err';else if(/✓/.test(html))k='ok';else if(/⚠/.test(html))k='warn';else if(/🔬/.test(html))k='probe';else if(/📥|🚀|📂/.test(html))k='info';else k='plain';}const div=document.createElement('div');div.className='pa-logline ll-'+k;div.innerHTML='<span class="ll-time">'+new Date().toLocaleTimeString()+'</span>'+html;el.appendChild(div);el.scrollTop=el.scrollHeight;}
function clErr(e){if(!e)return 'unknown';let s=e.message||JSON.stringify(e);if(e.error_user_msg)s+=' | '+e.error_user_msg;if(e.code)s+=' [code '+e.code+']';return s;}
function clPost(path,obj){const fd=new URLSearchParams();for(const k in obj){const v=obj[k];if(v===undefined||v===null)continue;fd.append(k,(typeof v==='object')?JSON.stringify(v):String(v));}fd.append('access_token',token);const doFetch=()=>apiCall('https://graph.facebook.com/v25.0/'+path,{method:'POST',body:fd});return (async()=>{if(clAbort)return {error:{code:-1,message:'stopped'}};let last=null;for(let att=0;att<6;att++){if(clAbort)break;let res;try{res=await doFetch();}catch(netE){last={error:{code:0,message:String(netE&&netE.message||netE)||'network'}};const w=2500*(att+1);clLog('&nbsp;&nbsp;&nbsp;&nbsp;<span style="color:var(--amber)">⏸ сеть: '+esc(last.error.message).slice(0,60)+' — повтор '+(att+1)+' через '+Math.round(w/1000)+'с…</span>');await new Promise(r=>setTimeout(r,w));continue;}const e=res&&res.error;const code=e&&e.code;const msg=e?clErr(e):'';const rate=!!e&&(code===4||code===17||code===32||code===613||(code>=80000&&code<=80099)||/request limit reached|too many calls|rate limit|throttl|temporarily unavailable/i.test(msg));if(rate){last=res;const w=6000*(att+1);clLog('&nbsp;&nbsp;&nbsp;&nbsp;<span style="color:var(--amber)">⏸ rate-limit [code '+code+'] — повтор '+(att+1)+'/5 через '+Math.round(w/1000)+'с…</span>');await new Promise(r=>setTimeout(r,w));continue;}return res;}return last;})();}
async function clPostRetry(path,obj,tries){for(let i=0;i<(tries||3);i++){const res=await clPost(path,obj);if(!res.error)return res;const code=res.error&&res.error.code;const msg=clErr(res.error);const transient=code===2||code===1||code===0||/unexpected|temporarily|try again later|service unavailable/i.test(msg);if(!transient)return res;clLog('&nbsp;&nbsp;⏸ '+esc(msg).slice(0,60)+' — повтор '+(i+1)+'/'+(tries||3)+'…');await new Promise(r=>setTimeout(r,4000*(i+1)));}return {error:{code:-1,message:'retries exhausted'}};}
function clDonorOpts(){const box=document.getElementById('cl-donor-list');if(!box)return;box.innerHTML=accs.map(a=>`<div class="ar-src-opt${a.id===clDonorId?' sel':''}" data-id="${a.id}"><span style="font-family:ui-monospace,monospace;color:#3b8cff;">${esc(accountId(a.id))}</span><span style="flex:1;color:#e8eaef;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${esc(a.name||'—')}</span><span style="font-size:10px;color:#9aa0ab;">${esc(a.currency||'')}</span></div>`).join('');box.querySelectorAll('.ar-src-opt').forEach(o=>{o.onclick=function(){clDonorId=this.dataset.id;const a=accs.find(x=>x.id===clDonorId);const inp=document.getElementById('cl-donor-search');if(inp&&a)inp.value=accountId(a.id)+' — '+(a.name||'');clDonorOpts();};});}
async function clLoadCampaigns(){if(!clDonorId){alert(t('cl_select_donor'));return;}clLog(()=>'📥 '+clDonorId+' …');try{const d=await fetchJson(`https://graph.facebook.com/v25.0/${clDonorId}/campaigns?fields=id,name,objective,status,bid_strategy,daily_budget,buying_type,special_ad_categories,is_adset_budget_sharing_enabled&limit=200&access_token=${encodeURIComponent(token)}`);clCampaigns=(d.data||[]).map(c=>{c.selected=true;return c;});clRenderCampaigns();clLog(()=>'✓ '+t('cl_found')+': '+clCampaigns.length);}catch(e){clLog('✗ '+clErr(e));}}
function clRenderCampaigns(){const box=document.getElementById('cl-camps');if(!box)return;if(!clCampaigns.length){box.innerHTML='<div class="pa-empty" style="padding:20px;">'+t('cl_no_camps')+'</div>';return;}box.innerHTML=clCampaigns.map((c,i)=>{const stc=(c.status==='ACTIVE')?'#37d67a':'#9aa0ab';return `<label class="ar-row"><input type="checkbox" class="pa-cb cl-camp-cb" data-i="${i}" ${c.selected?'checked':''}><span style="flex:1;font-size:12px;color:#e8eaef;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${esc(c.name)}</span><span style="color:${stc};font-size:10px;">● ${c.status||'?'}</span><span style="font-size:9px;color:#9aa0ab;font-family:ui-monospace,monospace;">${c.objective||''}</span></label>`;}).join('');box.querySelectorAll('.cl-camp-cb').forEach(cb=>{cb.onchange=function(){clCampaigns[+this.dataset.i].selected=this.checked;popCb(this);};});}
async function clExportStructure(){if(!clDonorId){alert(t('cl_select_donor'));return;}const sel=clCampaigns.filter(c=>c.selected);if(!sel.length){alert(t('cl_select_camps'));return;}clLog(()=>'📤 экспорт структуры донора '+clDonorId+' ('+sel.length+' камп.)…');const out={tool:'ParserAccs',kind:'clone-structure',donorId:clDonorId,exportedAt:new Date().toISOString(),campaigns:[]};for(const camp of sel){try{const adsets=await clFetchStructure(camp.id);out.campaigns.push({id:camp.id,name:camp.name,objective:camp.objective,status:camp.status,bid_strategy:camp.bid_strategy,daily_budget:camp.daily_budget,buying_type:camp.buying_type,special_ad_categories:camp.special_ad_categories||[],adsets:adsets});clLog(()=>'&nbsp;✓ '+esc(camp.name)+' · адсетов '+adsets.length);}catch(e){clLog(()=>'&nbsp;✗ '+esc(camp.name)+': '+esc(e.message));}}const json=JSON.stringify(out,null,2);const blob=new Blob([json],{type:'application/json;charset=utf-8;'});const url=URL.createObjectURL(blob);const aEl=document.createElement('a');aEl.href=url;aEl.download='parseraccs_clone_'+(clDonorId.replace(/^act_/,''))+'_'+stampNow()+'.json';document.body.appendChild(aEl);aEl.click();aEl.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);clLog(()=>'✓ структура сохранена в JSON ('+out.campaigns.length+' камп.)');}
function clImportStructure(file){const rd=new FileReader();rd.onload=ev=>{try{const raw=JSON.parse(String(ev.target.result||'').replace(/^\uFEFF/,''));const camps=Array.isArray(raw)?raw:(raw&&Array.isArray(raw.campaigns)?raw.campaigns:null);if(!camps||!camps.length){alert('JSON не распознан (нужен массив campaigns или {campaigns:[…], donorId})');return;}if(raw&&raw.donorId){clDonorId=raw.donorId;const inp=document.getElementById('cl-donor-search');if(inp)inp.value=raw.donorId+' (из файла)';clDonorOpts();}clCampaigns=camps.map(c=>({id:c.id,name:c.name,objective:c.objective,status:c.status,bid_strategy:c.bid_strategy,daily_budget:c.daily_budget,buying_type:c.buying_type,special_ad_categories:c.special_ad_categories||[],selected:true,_adsets:c.adsets||[]}));clRenderCampaigns();let nA=0,nAd=0;clCampaigns.forEach(c=>{(c._adsets||[]).forEach(a=>{nA++;nAd+=(a._ads||[]).length;});});clLog(()=>'📂 структура загружена из файла: кампаний '+clCampaigns.length+' · адсетов '+nA+' · объявлений '+nAd+' (оффлайн‑клон, без запроса к донору)');}catch(e){alert('Ошибка чтения JSON: '+e.message);}};rd.readAsText(file);}
function clGetTargets(){let list=accs;if(clFilter==='active')list=list.filter(a=>isAct(a.account_status));else if(clFilter==='disabled')list=list.filter(a=>!isAct(a.account_status));const s=(document.getElementById('cl-search')||{}).value||'';if(s){const q=s.toLowerCase();list=list.filter(a=>(a.name||'').toLowerCase().includes(q)||a.id.includes(q)||(a.accessibleBM?.name||'').toLowerCase().includes(q));}if(clSortMode==='camps_first'){list=list.filter(a=>clCampCounts[a.id]&&clCampCounts[a.id].count>0);}else if(clSortMode==='no_camps_first'){list=list.filter(a=>clCampCounts[a.id]&&clCampCounts[a.id].count===0);}else if(clSortMode==='name'){list=list.slice();list.sort((a,b)=>(a.name||'').localeCompare(b.name||''));}else if(clSortMode==='id'){list=list.slice();list.sort((a,b)=>String(a.id).localeCompare(String(b.id)));}return list;}
function clRenderTargets(){const box=document.getElementById('cl-targets');if(!box)return;const list=clGetTargets();box.innerHTML=list.map(a=>{const st=stM[a.account_status]||{t:'?',c:'#8a8d91'};const chk=clSelectedTargets.has(a.id);const actNum=(a.id||'').replace(/^act_/,'');return `<div class="ar-tgt"><input type="checkbox" class="pa-cb cl-tgt-cb" data-id="${a.id}" ${chk?'checked':''}><a href="https://www.facebook.com/adsmanager/manage/campaigns?act=${actNum}" target="_blank" class="pa-link">${accountId(a.id)}</a><span style="flex:1;font-size:11px;color:#e8eaef;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${esc(a.name||'—')}</span><span class="cl-rc" data-clc="${a.id}" style="font-size:10px;color:#9aa0ab;" title="кампаний в кабинете">…</span><span style="color:${st.c};font-size:10px;">● ${st.t}</span></div>`;}).join('')||'<div class="pa-empty" style="padding:16px;">'+t('empty')+'</div>';box.querySelectorAll('.cl-tgt-cb').forEach(cb=>{cb.onchange=function(){if(this.checked)clSelectedTargets.add(this.dataset.id);else clSelectedTargets.delete(this.dataset.id);popCb(this);clUpdateCnt();};});clUpdateCnt();paintVisibleClCounts();}
function clUpdateCnt(){const el=document.getElementById('cl-tgtcnt');const vis=clGetTargets();const sel=vis.filter(a=>clSelectedTargets.has(a.id)).length;if(el)el.innerHTML='<b style="color:#2dd4bf;">'+sel+'</b><span style="color:#6b7280;"> / '+vis.length+'</span>';const hdr=document.getElementById('cl-hdr-cb');if(hdr)hdr.checked=vis.length>0&&sel===vis.length;}
function paintClCount(id){const c=clCampCounts[id];document.querySelectorAll('[data-clc="'+id+'"]').forEach(el=>{if(!c){el.textContent='…';el.style.color='#9aa0ab';}else if(c.err){el.textContent='?';el.style.color='#ff5d6c';}else{el.innerHTML='<span style="color:'+(c.count>0?'#37d67a':'#9aa0ab')+';font-weight:700;">'+c.count+'</span> <span style="color:#9aa0ab">'+(LANG==='ru'?'камп.':'camps')+'</span>';}});}
function paintVisibleClCounts(){modal.querySelectorAll('#pa-tab-clone [data-clc]').forEach(el=>paintClCount(el.getAttribute('data-clc')));}
function clLoadCampCounts(list){return runBatched(list,12,async a=>{try{const d=await fetchJson(`https://graph.facebook.com/v25.0/${a.id}/campaigns?fields=id&limit=1&summary=1&access_token=${encodeURIComponent(token)}`);const cnt=(d.summary&&typeof d.summary.total_count==='number')?d.summary.total_count:(d.data?d.data.length:0);clCampCounts[a.id]={count:cnt};}catch(e){clCampCounts[a.id]={count:0,err:1};}paintClCount(a.id);}).then(()=>{clRenderTargets();});}
const clPad2=n=>String(n).padStart(2,'0');function clGeoOf(tg){if(!tg||!tg.geo_locations)return [];const g=tg.geo_locations;let a=(g.countries||[]).slice();if(!a.length){['regions','cities','zips','geo_markets','electoral_districts'].forEach(k=>{(g[k]||[]).forEach(x=>{if(x&&x.country)a.push(x.country);});});}if(!a.length&&Array.isArray(g.country_groups))a=g.country_groups.slice();return a.map(x=>String(x).toUpperCase());}function clGeoStr(ctx){const out=[];const add=tg=>clGeoOf(tg).forEach(c=>{if(out.indexOf(c)<0)out.push(c);});if(ctx&&ctx.as)add(ctx.as.targeting);else if(ctx&&ctx.camp)(ctx.camp._adsets||[]).forEach(a=>add(a.targeting));return out.join('-');}function clMacros(s,tgt,ctx){s=String(s==null?'':s);if(s.indexOf('{')<0)return s;ctx=ctx||{};const tgtNum=String(tgt||'').replace(/^act_/,'');const acc=accs.find(a=>a.id===tgt)||{};const d=new Date();const lvl=ctx.lvl||'';const bud=lvl==='camp'?(ctx.camp&&ctx.camp.daily_budget):(ctx.as&&ctx.as.daily_budget);const V={idacc:tgtNum,act:'act_'+tgtNum,accname:acc.name||'',currency:acc.currency||'',donor:String(clDonorId||'').replace(/^act_/,''),date:clPad2(d.getDate())+'.'+clPad2(d.getMonth()+1)+'.'+d.getFullYear(),dd:clPad2(d.getDate()),mm:clPad2(d.getMonth()+1),yy:String(d.getFullYear()).slice(2),yyyy:String(d.getFullYear()),time:clPad2(d.getHours())+'-'+clPad2(d.getMinutes()),geo:clGeoStr(ctx),name:ctx.orig!=null?String(ctx.orig):'',camp:(ctx.camp&&ctx.camp.name)||'',adset:(ctx.as&&ctx.as.name)||'',ad:(ctx.ad&&ctx.ad.name)||'',n:ctx.i!=null?String(ctx.i+1):'1',page:(ctx.page&&ctx.page.name)||'',pageid:(ctx.page&&ctx.page.id)?String(ctx.page.id):'',objective:String((ctx.camp&&ctx.camp.objective)||'').replace(/^OUTCOME_/,''),budget:bud?String(Math.round(parseFloat(bud))/100):'',rand:String(Math.floor(1000+Math.random()*9000))};return s.split('{{TGT_ID_NUM}}').join(tgtNum).split('{{TGT_ID}}').join('act_'+tgtNum).replace(/\{([a-zA-Z_]+)\}/g,(m,k)=>{const kk=k.toLowerCase();return Object.prototype.hasOwnProperty.call(V,kk)?V[kk]:m;});}function clTplSave(){try{const g=id=>(document.getElementById(id)||{}).value;localStorage.setItem('pa_cl_tpl',JSON.stringify({mode:clNameMode,camp:g('cl-tpl-camp'),adset:g('cl-tpl-adset'),ad:g('cl-tpl-ad')}));}catch(e){}}function clTplLoad(){let o=null;try{o=JSON.parse(localStorage.getItem('pa_cl_tpl')||'null');}catch(e){}if(!o)return;['camp','adset','ad'].forEach(k=>{const el=document.getElementById('cl-tpl-'+k);if(el&&typeof o[k]==='string')el.value=o[k];});const sel=document.getElementById('cl-naming');if(sel&&o.mode&&[...sel.options].some(x=>x.value===o.mode)){sel.value=o.mode;clNameMode=o.mode;const fr=document.getElementById('cl-fr-row');if(fr)fr.style.display=clNameMode==='findrep'?'flex':'none';const tr=document.getElementById('cl-tpl-row');if(tr)tr.style.display=clNameMode==='template'?'flex':'none';}}function clBuildName(orig,tgt,ctx){ctx=Object.assign({},ctx||{},{orig:orig});let s=String(orig||'');const srcNum=(clDonorId||'').replace(/^act_/,'');const tgtNum=(tgt||'').replace(/^act_/,'');if(clNameMode==='template'){const lvl=ctx.lvl||'ad';const id=lvl==='camp'?'cl-tpl-camp':(lvl==='adset'?'cl-tpl-adset':'cl-tpl-ad');const tp=String((document.getElementById(id)||{}).value||'').trim();if(tp)s=clMacros(tp,tgt,ctx).replace(/\s+/g,' ').trim()||s;}else if(clNameMode==='swap'&&srcNum){s=s.split('act_'+srcNum).join('act_'+tgtNum).split(srcNum).join(tgtNum);}else if(clNameMode==='findrep'){const f=(document.getElementById('cl-find')||{}).value||'';const r=clMacros((document.getElementById('cl-repl')||{}).value||'',tgt,ctx);if(f)s=s.split(f).join(r);}const so=document.getElementById('cl-sufon');if(so&&so.checked){const sv=clMacros((document.getElementById('cl-suf')||{}).value||'',tgt,ctx);if(sv)s+=sv;}return s;}
async function clPageName(id){if(!id)return '';if(clPageNameCache[id]!==undefined)return clPageNameCache[id];let n='';try{const d=await fetchJson(`https://graph.facebook.com/v25.0/${id}?fields=name&access_token=${encodeURIComponent(token)}`);n=d.name||'';}catch(e){}clPageNameCache[id]=n;return n;}
async function clGetPage(tgt,wantName){const key=tgt+'|'+(wantName||'');if(clPageCache[key]!==undefined)return clPageCache[key];let list=[];try{const d=await fetchJson(`https://graph.facebook.com/v25.0/${tgt}/promotable_pages?fields=id,name,is_published&limit=25&access_token=${encodeURIComponent(token)}`);list=(d.data||[]).filter(p=>p.is_published!==false);}catch(e){}if(!list.length){try{const d=await fetchJson(`https://graph.facebook.com/v25.0/me/accounts?fields=id,name,is_published&limit=25&access_token=${encodeURIComponent(token)}`);list=(d.data||[]).filter(p=>p.is_published!==false);}catch(e){}}let pg=null;if(wantName){const wn=clNorm(wantName);pg=list.find(p=>clNorm(p.name)===wn);}if(!pg)pg=list[0]||null;clPageCache[key]=pg;return pg;}
async function clResolvePage(tgt,donorPageId,fpOverride){if(fpOverride){const nm=await clPageName(fpOverride);const pg={id:fpOverride,name:nm||fpOverride};clLog('&nbsp;📄 '+t('cl_page')+': принудительно «'+esc(pg.name)+'» ('+fpOverride+')');return pg;}const donorPageName=await clPageName(donorPageId);const page=await clGetPage(tgt,donorPageName);if(page){if(donorPageName){const same=clNorm(page.name)===clNorm(donorPageName);clLog('&nbsp;📄 '+t('cl_page')+': донор «'+esc(donorPageName)+'» → цель «'+esc(page.name)+'» ('+page.id+')'+(same?'':' <span style="color:var(--amber)">⚠ имя не совпало</span>'));}else{clLog('&nbsp;📄 '+t('cl_page')+': '+esc(page.name)+' ('+page.id+')');}}else{clLog('&nbsp;⚠ '+t('cl_no_page'));}return page;}
function clRandBudget(){const el=document.getElementById('cl-rand-budget');if(!el||!el.checked)return null;const mn=parseFloat((document.getElementById('cl-rand-min')||{}).value);const mx=parseFloat((document.getElementById('cl-rand-max')||{}).value);if(!isFinite(mn)||!isFinite(mx)||mx<mn)return null;const v=mn+Math.random()*(mx-mn);return Math.round(v*100);}
async function clGetPageList(tgt){const key=tgt+'|list';if(clPageCache[key])return clPageCache[key];let list=[];try{const d=await fetchJson(`https://graph.facebook.com/v25.0/${tgt}/promotable_pages?fields=id,name,is_published&limit=50&access_token=${encodeURIComponent(token)}`);list=(d.data||[]).filter(p=>p.is_published!==false);}catch(e){}if(!list.length){try{const d=await fetchJson(`https://graph.facebook.com/v25.0/me/accounts?fields=id,name,is_published&limit=50&access_token=${encodeURIComponent(token)}`);list=(d.data||[]).filter(p=>p.is_published!==false);}catch(e){}}clPageCache[key]=list;return list;}
async function clDonorImageUrl(hash){if(!hash||!clDonorId)return '';const key='donorimg|'+hash;if(clThumbCache[key]!==undefined)return clThumbCache[key];let url='';try{const d=await fetchJson(`https://graph.facebook.com/v25.0/${clDonorId}/adimages?hashes=${encodeURIComponent(JSON.stringify([hash]))}&fields=hash,url&access_token=${encodeURIComponent(token)}`);const list=(d&&d.data)||Object.values(d||{});for(const it of list){if(it&&it.url){url=it.url;break;}}}catch(e){}clThumbCache[key]=url;return url;}
async function clResolveThumb(tgt,f){const url=f&&f.thumb;const dhash=f&&f.imageHash;if(!url&&!dhash)return null;const key=tgt+'|'+(url||('h:'+dhash));if(clThumbCache[key]!==undefined)return clThumbCache[key];let hash=null;let u=url;if(!u&&dhash){u=await clDonorImageUrl(dhash);}if(u){try{const r=await clPost(tgt+'/adimages',{url:u,name:'pa_clone_thumb'});const imgs=r&&r.images;if(imgs){const arr=Object.values(imgs);if(arr[0]&&arr[0].hash)hash=arr[0].hash;}if(!hash&&r&&r.hash)hash=r.hash;}catch(e){}}if(!hash&&dhash)hash=dhash;clThumbCache[key]=hash;return hash;}
async function clPixelList(tgt){if(clPixelListCache[tgt])return clPixelListCache[tgt];let list=[];try{const d=await fetchJson(`https://graph.facebook.com/v25.0/${tgt}/adspixels?fields=id,name&limit=50&access_token=${encodeURIComponent(token)}`);list=d.data||[];}catch(e){}clPixelListCache[tgt]=list;return list;}
async function clResolvePixel(tgt,wantName){const list=await clPixelList(tgt);if(!list.length)return null;if(wantName){const n=clNorm(wantName);const m=list.find(p=>clNorm(p.name)===n);if(m)return m;}return list[0];}
async function clDonorPixelName(pid){if(!pid)return '';if(clDonorPixelNameCache[pid]!==undefined)return clDonorPixelNameCache[pid];let nm='';try{const d=await fetchJson(`https://graph.facebook.com/v25.0/${pid}?fields=name&access_token=${encodeURIComponent(token)}`);nm=d.name||'';}catch(e){}clDonorPixelNameCache[pid]=nm;return nm;}
async function clGetPageToken(pageId){if(!pageId)return null;if(clPageTokenCache[pageId]!==undefined)return clPageTokenCache[pageId];let tok=null;try{const d=await fetchJson(`https://graph.facebook.com/v25.0/me/accounts?fields=id,access_token&limit=50&access_token=${encodeURIComponent(token)}`);const p=(d.data||[]).find(x=>String(x.id)===String(pageId));if(p&&p.access_token)tok=p.access_token;}catch(e){}clPageTokenCache[pageId]=tok;return tok;}
async function clGetInstagramActor(tgt,pageId,strict){const key=tgt+'|'+(pageId||'')+(strict?'|s':'');if(clIgCache[key]!==undefined)return clIgCache[key];let ig=null,via='';const probe=[];const rec=(label,val,err)=>{probe.push(label+'='+(err?('✗'+(err||'err')):(val?('✓'+val):'∅')));};if(!strict){try{const d=await fetchJson(`https://graph.facebook.com/v25.0/${tgt}/connected_instagram_accounts?fields=id,username&limit=10&access_token=${encodeURIComponent(token)}`);if(d.data&&d.data.length){ig=d.data[0];via='connected';rec('connected',ig.id);}else rec('connected',null);}catch(e){rec('connected',null,(e&&e.message||'').slice(0,40));}}if(!ig&&pageId){try{const d=await fetchJson(`https://graph.facebook.com/v25.0/${pageId}?fields=instagram_business_account{id,username}&access_token=${encodeURIComponent(token)}`);if(d.instagram_business_account&&d.instagram_business_account.id){ig={id:d.instagram_business_account.id,username:d.instagram_business_account.username||''};via='page-ig-business';rec('ig-biz',ig.id);}else rec('ig-biz',null);}catch(e){rec('ig-biz',null,(e&&e.message||'').slice(0,40));}}const pt=await clGetPageToken(pageId);const tok=pt||token;if(!ig&&pageId){try{const d=await fetchJson(`https://graph.facebook.com/v25.0/${pageId}/page_backed_instagram_accounts?fields=id,username&access_token=${encodeURIComponent(tok)}`);if(d.data&&d.data.length){ig=d.data[0];via='page-backed';rec('backed',ig.id);}else rec('backed',null);}catch(e){rec('backed',null,(e&&e.message||'').slice(0,40));}}if(!ig&&pageId){try{const d=await fetchJson(`https://graph.facebook.com/v25.0/${pageId}/instagram_accounts?fields=id,username&access_token=${encodeURIComponent(tok)}`);if(d.data&&d.data.length){ig=d.data[0];via='page-ig';rec('page-ig',ig.id);}else rec('page-ig',null);}catch(e){rec('page-ig',null,(e&&e.message||'').slice(0,40));}}if(!ig&&pageId&&pt){try{const r=await apiCall(`https://graph.facebook.com/v25.0/${pageId}/page_backed_instagram_accounts?access_token=${encodeURIComponent(pt)}`,{method:'POST'});if(r&&r.id){ig={id:r.id,username:'(page-backed, создан)'};via='created';rec('create-pt',ig.id);}else rec('create-pt',null);}catch(e){rec('create-pt',null,(e&&e.message||'').slice(0,40));}}if(!ig&&pageId){try{const r=await apiCall(`https://graph.facebook.com/v25.0/${pageId}/page_backed_instagram_accounts?access_token=${encodeURIComponent(token)}`,{method:'POST'});if(r&&r.id){ig={id:r.id,username:'(page-backed, создан user-token)'};via='created-user';rec('create-user',ig.id);}else rec('create-user',null);}catch(e){rec('create-user',null,(e&&e.message||'').slice(0,40));}}if(ig)ig._via=via;clIgCache[key]=ig;if(!ig)clLog('&nbsp;🔬 ig-probe (page='+esc(pageId||'∅')+(pt?' · page-token=✓':' · page-token=∅')+'): '+esc(probe.join(' · ')));return ig;}
function clCleanTargeting(t){if(!t)return t;const c=JSON.parse(JSON.stringify(t));delete c.custom_audiences;delete c.excluded_custom_audiences;delete c.connections;delete c.excluded_connections;return c;}
function clPatchOss(oss,page,igObj){const o=JSON.parse(JSON.stringify(oss||{}));if(page)o.page_id=page.id;else delete o.page_id;delete o.instagram_actor_id;if(igObj&&igObj.id)o.instagram_user_id=igObj.id;else delete o.instagram_user_id;return o;}
function clExtractCreative(cr){const out={feed:null,feedRaw:null,video:'',link:'',message:'',title:'',description:'',caption:'',cta:'',thumb:'',imageHash:'',ig:'',objectType:'',productSet:'',templateUrlSpec:null,ossRaw:null};if(cr.asset_feed_spec){out.feed=cr.asset_feed_spec;out.feedRaw=cr.asset_feed_spec;try{const af=cr.asset_feed_spec;if(af.videos&&af.videos[0])out.video=af.videos[0].video_id||'';if(af.link_urls&&af.link_urls[0])out.link=af.link_urls[0].website_url||'';if(af.bodies&&af.bodies[0])out.message=af.bodies[0].text||'';if(af.titles&&af.titles[0])out.title=af.titles[0].text||'';if(af.descriptions&&af.descriptions[0])out.description=af.descriptions[0].text||'';if(af.call_to_action_types&&af.call_to_action_types[0])out.cta=af.call_to_action_types[0];}catch(e){}}out.objectType=cr.object_type||'';out.productSet=cr.product_set_id||'';out.templateUrlSpec=cr.template_url_spec||null;const oss=cr.object_story_spec;if(oss&&typeof oss==='object'){out.ossRaw=oss;if(oss.instagram_user_id||oss.instagram_actor_id)out.ig=oss.instagram_user_id||oss.instagram_actor_id;const vd=oss.video_data,ld=oss.link_data,pd=oss.photo_data;if(vd){if(!out.video)out.video=vd.video_id||'';if(!out.message)out.message=vd.message||'';if(!out.title)out.title=vd.title||'';if(!out.description)out.description=vd.description||'';if(!out.caption)out.caption=vd.caption||'';if(!out.thumb)out.thumb=vd.image_url||'';if(!out.imageHash)out.imageHash=vd.image_hash||'';if(!out.link)out.link=(vd.call_to_action&&vd.call_to_action.value&&vd.call_to_action.value.link)||vd.link||'';if(!out.cta)out.cta=(vd.call_to_action&&vd.call_to_action.type)||'';}if(ld){if(!out.link)out.link=ld.link||'';if(!out.message)out.message=ld.message||'';if(!out.title)out.title=ld.name||'';if(!out.description)out.description=ld.description||'';if(!out.caption)out.caption=ld.caption||'';if(!out.thumb)out.thumb=ld.picture||'';if(!out.cta)out.cta=(ld.call_to_action&&ld.call_to_action.type)||'';if(!out.productSet&&ld.product_set)out.productSet=ld.product_set;}if(pd){if(!out.thumb)out.thumb=pd.url||'';if(!out.message)out.message=pd.message||'';}}if(!out.thumb)out.thumb=cr.thumbnail_url||'';if(!out.imageHash)out.imageHash=cr.image_hash||'';if(!out.productSet&&cr.product_set_id)out.productSet=cr.product_set_id;return out;}
function clCtaObj(f){if(!f.cta)return undefined;if(f.link)return{type:f.cta,value:{link:f.link}};return{type:f.cta};}
function clDefaultCta(obj){const o=String(obj||'').toUpperCase();if(o.indexOf('SALES')>=0||o.indexOf('CONVERSION')>=0)return 'SHOP_NOW';if(o.indexOf('LEAD')>=0)return 'SIGN_UP';if(o.indexOf('TRAFFIC')>=0)return 'LEARN_MORE';if(o.indexOf('ENGAGEMENT')>=0)return 'LEARN_MORE';return 'LEARN_MORE';}
function clSingleSpecs(f,thumbHash){const out=[];const cta=clCtaObj(f);if(f.video){const vd={video_id:f.video};if(thumbHash)vd.image_hash=thumbHash;else if(f.thumb)vd.image_url=f.thumb;if(f.message)vd.message=f.message;if(f.title)vd.title=f.title;if(f.description)vd.description=f.description;if(f.caption)vd.caption=f.caption;if(cta)vd.call_to_action=cta;out.push({tag:'video',data:{video_data:vd}});const vd2={video_id:f.video};if(thumbHash)vd2.image_hash=thumbHash;if(f.message)vd2.message=f.message;if(cta)vd2.call_to_action=cta;out.push({tag:'video-min',data:{video_data:vd2}});}if(f.link){const ld={link:f.link};if(thumbHash)ld.picture=thumbHash;else if(f.thumb)ld.picture=f.thumb;if(f.message)ld.message=f.message;if(f.title)ld.name=f.title;if(f.description)ld.description=f.description;if(f.caption)ld.caption=f.caption;if(cta)ld.call_to_action=cta;out.push({tag:'link',data:{link_data:ld}});}return out;}
